              <label for="email-address">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
              <input
                id="email-address"
                name="email"
                type="email"
                autocomplete="email"
                required
                aria-describedby="email-address-error"
              />
              <div id="email-address-error" class="field-error" aria-live="polite"></div>
            </div>

            <div class="form-field">
              <label for="phone-number">Phone number</label>
              <input
                id="phone-number"
                name="phone"
                type="tel"
                autocomplete="tel"
                aria-describedby="phone-number-help phone-number-error"
                placeholder="+1 555 123 4567"
              />
              <div id="phone-number-help" class="field-help">
