     <script>
       const form = document.getElementById("support-form");
       const fields = [
         {
           input: document.getElementById("full-name"),
           error: document.getElementById("full-name-error"),
           message: "Enter your full name.",
           validate: (value) => value.trim().length > 0,
         },
         {
           input: document.getElementById("email-address"),
           error: document.getElementById("email-address-error"),
           message: "Enter a valid email address.",
           validate: (value) => value.trim().length > 0 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value),
         },
         {
           input: document.getElementById("phone-number"),
           error: document.getElementById("phone-number-error"),
           message: "",
           validate: () => true,
         },
       ];

       function clearFieldState(field) {
         field.input.removeAttribute("aria-invalid");
         field.error.textContent = "";
       }

       function setFieldError(field, message) {
         field.input.setAttribute("aria-invalid", "true");
         field.error.textContent = message;
       }

       function validateForm() {
         let firstInvalid = null;

         fields.forEach((field) => {
           clearFieldState(field);

           if (!field.validate(field.input.value)) {
             setFieldError(field, field.message);
             if (!firstInvalid) {
               firstInvalid = field.input;
             }
           }
         });

         return firstInvalid;
       }

       fields.forEach((field) => {
         field.input.addEventListener("input", () => {
           if (field.input.hasAttribute("aria-invalid")) {
             clearFieldState(field);
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const firstInvalid = validateForm();
         if (firstInvalid) {
           firstInvalid.focus();
           return;
         }

         form.reset();
       });
